{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyMwKllgPfoaICWiUKdhKwU0"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":5,"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"n9G3Csk_yCre","executionInfo":{"status":"ok","timestamp":1795528102271,"user_tz":-180,"elapsed":22,"user":{"displayName":"ANN NJERI","userId":"03208518039206983853"}},"outputId":"fe5bf7e9-5a1d-4e3e-bec1-fd91cdbc7148"},"outputs":[{"output_type":"stream","name":"stdout","text":["Generated duka_sales.csv, agents.csv, and agent_transactions.csv.\n"]}],"source":["import numpy as np\n","import pandas as pd\n","# Engagement 1: Duka Electronics (seed 2026) ---\n","rng = np.random.default_rng(2026)\n","n = 1000\n","products = {\n","    \"Phone\": 15000,\n","    \"Laptop\": 65000,\n","    \"Headphones\": 2500,\n","    \"Tablet\": 28000,\n","    \"Charger\": 1200,\n","}\n","\n","sales = pd.DataFrame({\n","    \"order_id\": range(1001, 1001 + n),\n","    \"order_date\": pd.to_datetime(\"2026-01-01\")\n","    + pd.to_timedelta(rng.integers(0, 180, n), unit=\"D\"),\n","    \"branch\": rng.choice(\n","        [\"Nairobi\", \"Mombasa\", \"Kisumu\", \"Nakuru\", \"Eldoret\"],\n","        n,\n","        p=[0.4, 0.2, 0.15, 0.15, 0.1],\n","    ),\n","    \"product\": rng.choice(list(products), n),\n","    \"quantity\": rng.integers(1, 6, n),\n","    \"channel\": rng.choice(\n","        [\"In-store\", \"Online\", \"Phone order\"],\n","        n,\n","        p=[0.55, 0.35, 0.10],\n","    ),\n","})\n","sales[\"unit_price\"] = sales[\"product\"].map(products)\n","sales.to_csv(\"duka_sales.csv\", index=False)\n","\n","\n","# Engagement 2: Mobile Money Agent Network (seed 44) ---\n","rng = np.random.default_rng(44)\n","n = 600\n","agents = pd.DataFrame({\n","    \"agent_id\": [f\"AG{i:03d}\" for i in range(1, 21)],\n","    \"county\": rng.choice([\"Nairobi\", \"Kiambu\", \"Nakuru\", \"Mombasa\", \"Kisumu\"], 20),\n","    \"onboarded\": pd.date_range(\"2024-01-01\", periods=20, freq=\"MS\").strftime(\"%Y-%m-%d\"),\n","})\n","txns = pd.DataFrame({\n","    \"txn_id\": [f\"TX{i:05d}\" for i in range(1, n + 1)],\n","    \"agent_id\": rng.choice(agents[\"agent_id\"], n),\n","    \"txn_type\": rng.choice(\n","        [\"Deposit\", \"withdrawal\", \"DEPOSIT \", \"Withdrawal\", \"deposit\"], n\n","    ),\n","    \"amount\": rng.lognormal(7.5, 0.8, n).round(0).astype(str),\n","    \"txn_date\": (\n","        pd.to_datetime(\"2026-03-01\")\n","        + pd.to_timedelta(rng.integers(0, 60, n), unit=\"D\")\n","    ).strftime(\"%Y-%m-%d\"),\n","})\n","idx = rng.choice(n, 30, replace=False)\n","txns.loc[idx[:15], \"amount\"] = np.nan\n","txns.loc[idx[15:20], \"amount\"] = \"N/A\"\n","txns.loc[idx[20:25], \"amount\"] = \"250000\"\n","txns.loc[idx[25:], \"txn_date\"] = txns.loc[idx[25:], \"txn_date\"].str.replace(\"-\", \"/\")\n","txns = pd.concat([txns, txns.sample(12, random_state=1)], ignore_index=True)\n","txns.loc[rng.choice(len(txns), 8, replace=False), \"agent_id\"] = \"AG099\"\n","agents.to_csv(\"agents.csv\", index=False)\n","txns.to_csv(\"agent_transactions.csv\", index=False)\n","\n","print(\"Generated duka_sales.csv, agents.csv, and agent_transactions.csv.\")"]}]}